function describeGroup(group) {
  if (Array.isArray(group.target_commands)) {
    return {
      title: group.title,
      meta: `${group.target_commands.length} commands`,
      text: group.migration_note,
    };
  }

  return {
    title: group.title,
    meta: `${group.command_count} commands / ${group.safety}`,
    text: `${group.phase}: ${group.summary}`,
  };
}

