function describeToolbarCommand(command) {
  const state = command.state ?? "disabled";
  return {
    title: command.label,
    meta: `${state} / ${command.capability_tier}`,
    text: command.unavailable_reason || command.verification,
    state,
  };
}

function toolbarCommandSearchText(command) {
  return [
    command.id,
    command.label,
    command.current_action,
    command.target_command,
    command.state,
    command.capability_tier,
    command.unavailable_reason,
    command.verification,
  ]
    .filter(Boolean)
    .join(" ")
    .toLowerCase();
}

function filterToolbarCommands(commands, query) {
  const normalized = query.trim().toLowerCase();
  if (!normalized) {
    return commands;
  }

  const terms = normalized.split(/\s+/).filter(Boolean);
  return commands.filter((command) => {
    const haystack = toolbarCommandSearchText(command);
    return terms.every((term) => haystack.includes(term));
  });
}

function renderToolbarRegistry(commands, query = "") {
  clearList(toolbarList);
  const filtered = filterToolbarCommands(commands, query);
  toolbarSearchSummary.textContent = query.trim()
    ? `${filtered.length} of ${commands.length} commands`
    : "All toolbar commands shown.";

  if (filtered.length === 0) {
    toolbarList.append(item("No matching toolbar commands", "empty", "Clear the search field to restore the full command registry."));
    return;
  }

  for (const command of filtered) {
    const view = describeToolbarCommand(command);
    const node = item(view.title, view.meta, view.text);
    node.dataset.state = view.state;
    const actions = document.createElement("div");
    actions.className = "panel-actions";
    actions.append(toolbarDryRunButton(command));
    node.append(actions);
    toolbarList.append(node);
  }
}

function focusToolbarSearch() {
  applyRailArea("command");
  toolbarSearchInput?.scrollIntoView({ block: "center", behavior: "smooth" });
  toolbarSearchInput?.focus({ preventScroll: true });
  toolbarSearchInput?.select();
  statusEl.textContent = "Command search focused";
  statusEl.classList.remove("error");
  statusEl.classList.add("ok");
}

function toolbarDryRunButton(command) {
  const button = document.createElement("button");
  button.type = "button";
  button.className = "panel-mini-btn";
  button.textContent = command.state === "live" ? "Open" : command.state === "gated" ? "Dry Run Gate" : "Dry Run";
  button.title = command.state === "live" ? `Open ${command.label}` : `Dry-run ${command.label}`;
  button.addEventListener("click", async () => {
    button.disabled = true;
    try {
      if (command.target_command === "docs_open") {
        const panel = await loadBundledDocsPanel();
        renderBundledDocsPanel(panel);
        renderCommandResolution({
          id: command.id,
          status: "live",
          target_command: command.target_command,
          reason: "Bundled docs panel opened in app.",
        });
        statusEl.textContent = `${command.label} opened`;
        statusEl.classList.remove("error");
        statusEl.classList.add("ok");
        return;
      }

      if (command.target_command === "about_open") {
        const panel = await loadAboutPanel();
        renderAboutPanel(panel);
        renderCommandResolution({
          id: command.id,
          status: "live",
          target_command: command.target_command,
          reason: "Bundled About panel opened in app.",
        });
        statusEl.textContent = `${command.label} opened`;
        statusEl.classList.remove("error");
        statusEl.classList.add("ok");
        return;
      }

      if (command.target_command === "command_palette_open") {
        const panel = await loadCommandPalettePanel();
        renderCommandPalettePanel(panel);
        renderCommandResolution({
          id: command.id,
          status: "live",
          target_command: command.target_command,
          reason: "Read-only command palette opened in app.",
        });
        statusEl.textContent = `${command.label} opened`;
        statusEl.classList.remove("error");
        statusEl.classList.add("ok");
        return;
      }

      if (command.target_command === "terminal_toggle") {
        const panel = await loadTerminalTogglePanel();
        renderTerminalTogglePanel(panel);
        renderTerminalProcessLaneDashboard(panel.dashboard);
        renderCommandResolution({
          id: command.id,
          status: "live",
          target_command: command.target_command,
          reason: "Read-only terminal/process panel opened in app.",
        });
        statusEl.textContent = `${command.label} opened`;
        statusEl.classList.remove("error");
        statusEl.classList.add("ok");
        return;
      }

      if (command.target_command === "editor_find") {
        const panel = await loadFindPanel();
        renderFindPanel(panel);
        renderCommandResolution({
          id: command.id,
          status: "live",
          target_command: command.target_command,
          reason: "Read-only Find panel opened in app.",
        });
        statusEl.textContent = `${command.label} opened`;
        statusEl.classList.remove("error");
        statusEl.classList.add("ok");
        return;
      }

      if (command.target_command === "sswp_status") {
        const panel = await loadSswpStatusPanel();
        renderSswpStatusPanel(panel);
        renderCommandResolution({
          id: command.id,
          status: "live",
          target_command: command.target_command,
          reason: "Read-only SSWP status panel opened in app.",
        });
        statusEl.textContent = `${command.label} opened`;
        statusEl.classList.remove("error");
        statusEl.classList.add("ok");
        return;
      }

      if (command.target_command === "steno_search") {
        const panel = await loadStenoSearchPanel();
        renderStenoSearchPanel(panel);
        renderCommandResolution({
          id: command.id,
          status: "live",
          target_command: command.target_command,
          reason: "Read-only Steno Search panel opened in app.",
        });
        statusEl.textContent = `${command.label} opened`;
        statusEl.classList.remove("error");
        statusEl.classList.add("ok");
        return;
      }

      if (command.target_command === "first_class_integration_launchpad") {
        const panel = await loadFirstClassIntegrationLaunchpad(command.id);
        renderFirstClassIntegrationLaunchpad(panel);
        renderToolbarActionReadiness(await loadToolbarActionReadiness(command.id));
        renderCommandResolution({
          id: command.id,
          status: "live",
          target_command: command.target_command,
          reason: "Read-only first-class integration launchpad opened; underlying gated target remains disabled.",
        });
        statusEl.textContent = `${command.label} launchpad opened`;
        statusEl.classList.remove("error");
        statusEl.classList.add("ok");
        return;
      }

      if (command.target_command === "omega_computer_session") {
        renderToolbarActionReadiness(await loadToolbarActionReadiness(command.id));
        renderCommandResolution({
          id: command.id,
          status: "live",
          target_command: command.target_command,
          reason: "Omega Computer is live in the product toolbar; Codex Lead + Hermes/Kimi roles are recorded while desktop/action gates remain disabled.",
        });
        statusEl.textContent = `${command.label} is available in the product toolbar`;
        statusEl.classList.remove("error");
        statusEl.classList.add("ok");
        return;
      }

      if (
        command.target_command === "file_new" ||
        command.target_command === "file_pick" ||
        command.target_command === "workspace_open"
      ) {
        const files = await loadWorkspaceFilesDashboard();
        const navigation = await loadWorkspaceEditorNavigationLane();
        renderWorkspaceFilesDashboard(files);
        renderWorkspaceEditorNavigation(navigation);
        renderToolbarActionReadiness(await loadToolbarActionReadiness(command.id));
        const resolution = await resolveCommandStub(command.id);
        renderCommandResolution(resolution);
        statusEl.textContent = `${command.label} workspace surface opened`;
        statusEl.classList.remove("error");
        statusEl.classList.add("ok");
        return;
      }

      if (
        command.target_command === "editor_undo" ||
        command.target_command === "editor_redo"
      ) {
        const editFamily = await loadWorkspaceEditFamily();
        const workbench = await loadWorkspaceMutationWorkbench(command.id);
        renderWorkspaceEditFamily(editFamily);
        renderWorkspaceMutationWorkbench(workbench);
        renderToolbarActionReadiness(await loadToolbarActionReadiness(command.id));
        const resolution = await resolveCommandStub(command.id);
        renderCommandResolution(resolution);
        statusEl.textContent = `${command.label} workspace edit surface opened`;
        statusEl.classList.remove("error");
        statusEl.classList.add("ok");
        return;
      }

      if (
        command.target_command === "window_new" ||
        command.target_command === "window_toggle_fullscreen" ||
        command.target_command === "app_exit"
      ) {
        const workbench = await loadNativeShellPairingWorkbench(command.id);
        renderNativeShellPairingWorkbench(workbench);
        renderToolbarActionReadiness(await loadToolbarActionReadiness(command.id));
        const resolution = await resolveCommandStub(command.id);
        renderCommandResolution(resolution);
        statusEl.textContent = `${command.label} native shell surface opened`;
        statusEl.classList.remove("error");
        statusEl.classList.add("ok");
        return;
      }

      if (command.target_command === "codex_review") {
        const runView = await loadCodexHermesRunViewDashboard();
        const launchpad = await loadFirstClassIntegrationLaunchpad(command.id);
        renderCodexHermesRunView(runView);
        renderFirstClassIntegrationLaunchpad(launchpad);
        renderToolbarActionReadiness(await loadToolbarActionReadiness(command.id));
        const resolution = await resolveCommandStub(command.id);
        renderCommandResolution(resolution);
        statusEl.textContent = `${command.label} Codex/Hermes run view opened`;
        statusEl.classList.remove("error");
        statusEl.classList.add("ok");
        return;
      }

      if (
        command.target_command === "file_write" ||
        command.target_command === "file_save_as" ||
        command.target_command === "editor_replace"
      ) {
        const workbench = await loadWorkspaceMutationWorkbench(command.id);
        renderWorkspaceMutationWorkbench(workbench);
        renderGatedAdapterReleaseQueue(await loadGatedAdapterReleaseQueue());
        renderToolbarActionReadiness(await loadToolbarActionReadiness(command.id));
        const resolution = await resolveCommandStub(command.id);
        renderCommandResolution(resolution);
        statusEl.textContent = `${command.label} workspace mutation workbench opened`;
        statusEl.classList.remove("error");
        statusEl.classList.add("ok");
        return;
      }

      if (command.target_command === "terminal_create") {
        const workbench = await loadTerminalProcessWorkbench(command.id);
        renderTerminalProcessWorkbench(workbench);
        renderGatedAdapterReleaseQueue(await loadGatedAdapterReleaseQueue());
        renderToolbarActionReadiness(await loadToolbarActionReadiness(command.id));
        const resolution = await resolveCommandStub(command.id);
        renderCommandResolution(resolution);
        statusEl.textContent = `${command.label} terminal process workbench opened`;
        statusEl.classList.remove("error");
        statusEl.classList.add("ok");
        return;
      }

      if (
        command.target_command === "security_shield_action" ||
        command.target_command === "security_scan"
      ) {
        const workbench = await loadSecurityShieldWorkbench(command.id);
        renderSecurityShieldWorkbench(workbench);
        renderGatedAdapterReleaseQueue(await loadGatedAdapterReleaseQueue());
        renderToolbarActionReadiness(await loadToolbarActionReadiness(command.id));
        const resolution = await resolveCommandStub(command.id);
        renderCommandResolution(resolution);
        statusEl.textContent = `${command.label} security shield workbench opened`;
        statusEl.classList.remove("error");
        statusEl.classList.add("ok");
        return;
      }

      if (
        command.target_command === "devtools_toggle" ||
        command.target_command === "mobile_pairing_qr"
      ) {
        const workbench = await loadNativeShellPairingWorkbench(command.id);
        renderNativeShellPairingWorkbench(workbench);
        renderGatedAdapterReleaseQueue(await loadGatedAdapterReleaseQueue());
        renderToolbarActionReadiness(await loadToolbarActionReadiness(command.id));
        const resolution = await resolveCommandStub(command.id);
        renderCommandResolution(resolution);
        statusEl.textContent = `${command.label} native shell pairing workbench opened`;
        statusEl.classList.remove("error");
        statusEl.classList.add("ok");
        return;
      }

      if (command.state !== "live") {
        const readiness = await loadToolbarActionReadiness(command.id);
        renderToolbarActionReadiness(readiness);
        renderGatedAdapterReleaseQueue(await loadGatedAdapterReleaseQueue());
        const resolution = await resolveCommandStub(command.id);
        renderCommandResolution(resolution);
        statusEl.textContent = `${command.label} readiness opened`;
        statusEl.classList.remove("error");
        statusEl.classList.add("ok");
        return;
      }

      const readiness = await loadToolbarActionReadiness(command.id);
      renderToolbarActionReadiness(readiness);
      renderCommandResolution({
        id: command.id,
        status: "live",
        target_command: command.target_command,
        reason: "Live read-only toolbar intent opened in readiness center.",
      });
      statusEl.textContent = `${command.label} intent opened`;
      statusEl.classList.remove("error");
      statusEl.classList.add("ok");
      return;
    } catch (error) {
      statusEl.textContent = `Toolbar dry-run failed: ${error.message}`;
      statusEl.classList.add("error");
    } finally {
      button.disabled = false;
    }
  });
  return button;
}

