function renderSswpStatusPanel(panel) {
  if (!panel) {
    sswpStatusPanelSummary.textContent = "SSWP status panel unavailable.";
    sswpStatusPanelCount.textContent = "0";
    clearList(sswpStatusPanelList);
    return;
  }

  const lane = panel.lane ?? {};
  const highRisk = Number(panel.highest_risk_percent ?? 0).toFixed(1);
  sswpStatusPanelSummary.textContent = [
    panel.status,
    `evidence=${panel.ready_evidence_count}/${panel.evidence_record_count}`,
    `registry=${panel.registry_node_count ?? 0}/${panel.registry_snapshot_count ?? 0}`,
    `risky=${panel.risky_node_count ?? 0}`,
    `high=${highRisk}%`,
    `runtime=${panel.runtime_process_count ?? 0}`,
    `running=${Boolean(panel.runtime_running)}`,
    `commands=${panel.command_count}`,
    `disabled_gates=${panel.disabled_gate_count}`,
    `live_probe=${panel.live_probe_enabled}`,
    `live_call=${panel.live_call_enabled}`,
    `config=${panel.config_read_enabled}`,
    `socket=${panel.socket_connect_enabled}`,
    `exec=${panel.execution_enabled}`,
  ].join(" | ");

  clearList(sswpStatusPanelList);
  const records = [
    {
      title: `${panel.display_name} / ${lane.lane_role ?? "sovereign workflow protocol lane"}`,
      meta: `${panel.ready_evidence_count}/${panel.evidence_record_count} evidence / ${panel.command_count} commands`,
      text: `${lane.status ?? panel.status}. ${(lane.expected_command_ids ?? []).slice(0, 4).join(", ") || "commands pending"}. ${lane.next_action ?? panel.next_slice}`,
      state: panel.live_probe_enabled || panel.live_call_enabled || panel.config_read_enabled || panel.socket_connect_enabled || panel.capture_enabled || panel.export_enabled || panel.writes_allowed || panel.execution_enabled ? "gated" : "disabled",
    },
    {
      title: "Registry Snapshot",
      meta: `${panel.registry_node_count ?? 0} node(s) / ${panel.risky_node_count ?? 0} risky`,
      text: `${panel.latest_registry_snapshot_status ?? "waiting"}; highest=${highRisk}%; record=${panel.latest_registry_snapshot_path ?? "none"}; witness=false; verify=false`,
      state: panel.risky_node_count > 0 ? "gated" : "ready",
    },
    {
      title: "Runtime Process Evidence",
      meta: `${panel.runtime_health_status ?? "runtime_process_snapshot_waiting"} / running=${Boolean(panel.runtime_running)}`,
      text: `target=${panel.runtime_target_id ?? "sswp-mcp"}; pattern=${panel.runtime_expected_pattern ?? "mcp-servers/sswp"}; processes=${panel.runtime_process_count ?? 0}; snapshot=${panel.latest_runtime_process_snapshot_path ?? "none"}; liveCall=${panel.live_call_enabled}; exec=${panel.execution_enabled}`,
      state: panel.runtime_running ? "ready" : "disabled",
    },
    {
      title: "Disabled Gates",
      meta: `${panel.disabled_gate_count} sealed lane`,
      text: `probe=${panel.live_probe_enabled}; call=${panel.live_call_enabled}; config=${panel.config_read_enabled}; socket=${panel.socket_connect_enabled}; capture=${panel.capture_enabled}; export=${panel.export_enabled}; writes=${panel.writes_allowed}; exec=${panel.execution_enabled}`,
      state: "disabled",
    },
  ];

  sswpStatusPanelCount.textContent = String(records.length);
  for (const record of records) {
    const node = item(record.title, record.meta, record.text);
    node.dataset.state = record.state;
    sswpStatusPanelList.append(node);
  }
}

