function renderStenoSearchPanel(panel) {
  if (!panel) {
    stenoSearchPanelSummary.textContent = "Steno search panel unavailable.";
    stenoSearchPanelCount.textContent = "0";
    clearList(stenoSearchPanelList);
    return;
  }

  stenoSearchPanelSummary.textContent = [
    panel.status,
    `query="${panel.query}"`,
    `results=${panel.result_count}`,
    `matched=${panel.matched_file_count ?? 0}`,
    `searched=${panel.searched_file_count ?? 0}`,
    `limit=${panel.max_results ?? 0}`,
    `transcripts=${panel.transcript_bundle_ready_count}/${panel.transcript_bundle_count}`,
    `protection=${panel.transcript_protection_policy_ready_count}/${panel.transcript_protection_policy_count}`,
    `steno=${panel.steno_mcp_ready_count}/${panel.steno_mcp_evidence_count}`,
    `disabled_gates=${panel.disabled_gate_count}`,
    `read=${panel.transcript_read_enabled}`,
    `index=${panel.transcript_index_enabled}`,
    `capture=${panel.capture_enabled}`,
    `export=${panel.export_enabled}`,
    `exec=${panel.execution_enabled}`,
  ].join(" | ");

  clearList(stenoSearchPanelList);
  const results = panel.results ?? [];
  const sections = panel.sections ?? [];
  stenoSearchPanelCount.textContent = String(results.length);

  if ((panel.query ?? "").trim() && results.length === 0) {
    stenoSearchPanelList.append(
      item(
        "No Steno matches",
        `searched ${panel.searched_file_count ?? 0} approved files`,
        "Try a term from Omega Agent Work, terminal output, runtime evidence, pet signals, or Codex/Hermes run records.",
      ),
    );
  }

  for (const result of results) {
    const title = result.title || "Steno evidence match";
    const meta = [
      result.category || "evidence",
      result.line_number ? `line ${result.line_number}` : "",
      result.status || "read-only",
    ].filter(Boolean).join(" / ");
    const node = item(title, meta, `${result.snippet || ""}\n${result.record_path || ""}`);
    node.dataset.state = "ready";
    stenoSearchPanelList.append(node);
  }

  if (sections.length === 0) {
    if (results.length === 0) {
      stenoSearchPanelList.append(item("No Steno search readiness sections", "empty", "Refresh the read-only Steno search panel."));
    }
    return;
  }

  if (results.length > 0) {
    stenoSearchPanelList.append(item("Read-only Steno readiness", `${sections.length} sections`, "Search results above are local evidence/transcript records; capture/export/live MCP remain disabled."));
  }

  for (const record of sections) {
    const view = describeStenoPetCompanionSection(record);
    const node = item(view.title, view.meta, view.text);
    node.dataset.state = view.state;
    stenoSearchPanelList.append(node);
  }
}

async function refreshStenoSearchPanel(query = stenoSearchQueryInput?.value ?? "") {
  if (refreshStenoSearchPanelBtn) refreshStenoSearchPanelBtn.disabled = true;
  if (stenoSearchRunBtn) stenoSearchRunBtn.disabled = true;
  try {
    const panel = await loadStenoSearchPanel(query);
    renderStenoSearchPanel(panel);
    return panel;
  } finally {
    if (refreshStenoSearchPanelBtn) refreshStenoSearchPanelBtn.disabled = false;
    if (stenoSearchRunBtn) stenoSearchRunBtn.disabled = false;
  }
}

function describeTerminalSessionSummary(record) {
  const status = record.status ?? "terminal_session_unknown";
  const command = record.command ?? "none";
  const exit = record.exit_code ?? "none";
  const duration = record.duration_ms ?? 0;
  const stdoutBytes = record.stdout_size_bytes ?? 0;
  const stderrBytes = record.stderr_size_bytes ?? 0;
  return {
    title: `Terminal session: ${command}`,
    meta: `${status} / exit=${exit} / ${duration}ms`,
    text: `stdout=${stdoutBytes}b; stderr=${stderrBytes}b; stream=${record.source_stream_enabled ?? false}; sourceExec=${record.source_execution_enabled ?? false}; dashboardExec=${record.execution_enabled ?? false}; record=${record.record_path ?? "none"}`,
    state: record.timed_out ? "warning" : exit === 0 ? "ok" : status.includes("failed") ? "error" : "ready",
  };
}

function describeTerminalReplaySummary(record) {
  const status = record.status ?? "terminal_replay_unknown";
  const command = record.command ?? "none";
  const exit = record.exit_code ?? "none";
  const duration = record.duration_ms ?? 0;
  const stdoutLines = record.stdout_line_count ?? 0;
  const stderrLines = record.stderr_line_count ?? 0;
  const blockers = (record.blockers ?? []).length ? ` blockers=${record.blockers.join("; ")}` : "";
  return {
    title: `Terminal replay: ${command}`,
    meta: `${status} / exit=${exit} / ${duration}ms`,
    text: `stdoutLines=${stdoutLines}; stderrLines=${stderrLines}; transcriptRead=${record.transcript_read_enabled ?? false}; liveTail=${record.live_tail_enabled ?? false}; record=${record.record_path ?? "none"}${blockers}`,
    state: (record.blockers ?? []).length ? "warning" : "ready",
  };
}

function renderTerminalProcessLaneDashboard(dashboard) {
  if (!dashboard) {
    terminalProcessLaneDashboardSummary.textContent = "Terminal process lane dashboard unavailable.";
    terminalProcessLaneDashboardCount.textContent = "0";
    clearList(terminalProcessLaneDashboardList);
    return;
  }

  terminalProcessLaneDashboardSummary.textContent = [
    dashboard.status,
    `runners=${dashboard.runner_invocation_ready_count}/${dashboard.runner_invocation_count}`,
    `adapters=${dashboard.runner_adapter_ready_count}/${dashboard.runner_adapter_count}`,
    `plans=${dashboard.process_command_plan_ready_count}/${dashboard.process_command_plan_count}`,
    `streams=${dashboard.process_stream_init_ready_count}/${dashboard.process_stream_init_count}`,
    `supervisor=${dashboard.process_supervisor_preflight_ready_count}/${dashboard.process_supervisor_preflight_count}`,
    `tails=${dashboard.process_output_tail_summary_ready_count}/${dashboard.process_output_tail_summary_count}`,
    `sessions=${dashboard.recent_terminal_session_count ?? 0}`,
    `replays=${dashboard.recent_terminal_replay_count ?? 0}`,
    `disabled_gates=${dashboard.disabled_gate_count}`,
    `terminal=${dashboard.terminal_enabled}`,
    `spawn=${dashboard.process_spawn_enabled}`,
    `exec=${dashboard.execution_enabled}`,
  ].join(" | ");

  clearList(terminalProcessLaneDashboardList);
  const sections = dashboard.sections ?? [];
  const recentSessions = dashboard.recent_terminal_sessions ?? [];
  const recentReplays = dashboard.recent_terminal_replays ?? [];
  terminalProcessLaneDashboardCount.textContent = String(sections.length + recentSessions.length + recentReplays.length);

  for (const record of recentSessions.slice(0, 6)) {
    const view = describeTerminalSessionSummary(record);
    const node = item(view.title, view.meta, view.text);
    node.dataset.state = view.state;
    terminalProcessLaneDashboardList.append(node);
  }

  for (const record of recentReplays.slice(0, 6)) {
    const view = describeTerminalReplaySummary(record);
    const node = item(view.title, view.meta, view.text);
    node.dataset.state = view.state;
    terminalProcessLaneDashboardList.append(node);
  }

  if (sections.length === 0 && recentSessions.length === 0 && recentReplays.length === 0) {
    terminalProcessLaneDashboardList.append(item("No terminal/process lane records", "empty", "Run an allowed terminal command, then refresh the read-only terminal/process dashboard."));
    return;
  }

  for (const record of sections) {
    const view = describeTerminalProcessLaneSection(record);
    const node = item(view.title, view.meta, view.text);
    node.dataset.state = view.state;
    terminalProcessLaneDashboardList.append(node);
  }
}

async function refreshTerminalProcessLaneDashboard() {
  refreshTerminalProcessLaneDashboardBtn.disabled = true;
  try {
    const dashboard = await loadTerminalProcessLaneDashboard();
    renderTerminalProcessLaneDashboard(dashboard);
    return dashboard;
  } finally {
    refreshTerminalProcessLaneDashboardBtn.disabled = false;
  }
}

function renderTerminalProcessWorkbench(workbench) {
  if (!workbench) {
    terminalProcessWorkbenchSummary.textContent = "Terminal process workbench unavailable.";
    terminalProcessWorkbenchCount.textContent = "0";
    clearList(terminalProcessWorkbenchList);
    return;
  }

  terminalProcessWorkbenchSummary.textContent = [
    workbench.command_id,
    workbench.status,
    `selected=${workbench.selected_operation ?? "none"}`,
    `items=${workbench.item_count}`,
    `readyStages=${workbench.ready_stage_total}`,
    `blockedStages=${workbench.blocked_stage_total}`,
    `terminal=${workbench.terminal_enabled}`,
    `spawn=${workbench.process_spawn_enabled}`,
    `exec=${workbench.execution_enabled}`,
  ].join(" | ");

  clearList(terminalProcessWorkbenchList);
  const records = workbench.items ?? [];
  terminalProcessWorkbenchCount.textContent = String(records.length);

  if (records.length === 0) {
    terminalProcessWorkbenchList.append(item("No terminal process items", "empty", workbench.next_step ?? "No terminal process rows are available."));
    return;
  }

  for (const record of records) {
    const selected = record.command_id === workbench.command_id ? " (selected)" : "";
    const stageSummary = (record.stages ?? [])
      .map((stage) => `${stage.title}:${stage.status}`)
      .join(" -> ");
    const node = item(
      `${record.label}${selected}`,
      `${record.operation} / ${record.target_command ?? "no target"} / ${record.release_status}`,
      `${record.risk_summary} ${record.sandbox_policy} ${stageSummary}`,
    );
    node.dataset.state = record.terminal_enabled || record.process_spawn_enabled || record.stream_read_enabled || record.process_control_enabled || record.execution_enabled ? "gated" : "disabled";
    terminalProcessWorkbenchList.append(node);
  }
}

async function refreshTerminalProcessWorkbench(commandId = "terminal.new") {
  refreshTerminalProcessWorkbenchBtn.disabled = true;
  try {
    const workbench = await loadTerminalProcessWorkbench(commandId);
    renderTerminalProcessWorkbench(workbench);
    return workbench;
  } finally {
    refreshTerminalProcessWorkbenchBtn.disabled = false;
  }
}

function renderTerminalTogglePanel(panel) {
  if (!panel) {
    terminalTogglePanelSummary.textContent = "Terminal toggle panel unavailable.";
    terminalTogglePanelCount.textContent = "0";
    clearList(terminalTogglePanelList);
    return;
  }

  terminalTogglePanelSummary.textContent = [
    panel.status,
    panel.panel_title,
    `visible=${panel.visible}`,
    `sections=${panel.section_count}`,
    `ready=${panel.ready_section_count}`,
    `terminal=${panel.terminal_enabled}`,
    `spawn=${panel.process_spawn_enabled}`,
    `exec=${panel.execution_enabled}`,
  ].join(" | ");

  clearList(terminalTogglePanelList);
  const reasons = panel.reasons ?? [];
  terminalTogglePanelCount.textContent = String(reasons.length);

  if (reasons.length === 0) {
    terminalTogglePanelList.append(item("No terminal toggle reasons", "empty", "Refresh the read-only terminal toggle panel."));
    return;
  }

  terminalTogglePanelList.append(
    item(panel.panel_title, `${panel.panel_id} / ${panel.source_dashboard_status}`, panel.next_slice),
  );

  for (const reason of reasons) {
    const node = item("Terminal gate", "read-only", reason);
    node.dataset.state = "live";
    terminalTogglePanelList.append(node);
  }
}

async function refreshTerminalTogglePanel() {
  refreshTerminalTogglePanelBtn.disabled = true;
  try {
    const panel = await loadTerminalTogglePanel();
    renderTerminalTogglePanel(panel);
    renderTerminalProcessLaneDashboard(panel.dashboard);
    return panel;
  } finally {
    refreshTerminalTogglePanelBtn.disabled = false;
  }
}

