function evidenceAttachmentKind(metric) {
  if (metric === "ready_evidence_count") return "aggregate_ready_evidence_bundle";
  if (metric === "export_policy_ready_count") return "transcript_export_policy_evidence";
  if (metric === "protection_policy_ready_count") return "transcript_protection_policy_evidence";
  if (metric === "runner_ready_count") return "runner_readiness_evidence";
  if (metric === "transcript_bundle_ready_count") return "transcript_bundle_evidence";
  return "runtime_evidence_attachment";
}

