async function recordSswpRegistrySnapshot(requestedBy = "gravity-omega-ui") {
  const invoke = tauriInvoke();
  if (!invoke) {
    return null;
  }
  return invoke("record_sswp_registry_snapshot", {
    request: {
      requested_by: requestedBy,
      threshold: 0.3,
      timeout_ms: 15000,
    },
  });
}

