async function createTaskRunStub() {
  const invoke = tauriInvoke();
  if (!invoke) {
    statusEl.textContent = "Task run storage requires the Tauri runtime";
    statusEl.classList.add("error");
    return;
  }

  createTaskRunBtn.disabled = true;
  try {
    const run = await invoke("create_task_run_stub", {
      request: {
        mode: "joint_ci",
        repo: "/home/rage/apps/gravity-omega-rust-rebuild/rebuild/gravity-omega-tauri",
        prompt: "Create a blocked joint CI verification run for approval/logging evidence.",
      },
    });
    const records = await loadTaskRunLedger();
    const preview = await loadArtifactPreview(run.id);
    renderTaskRunLedger(records);
    renderArtifactPreview(preview);
    renderBottomEvidenceDock(records, preview);
  } finally {
    createTaskRunBtn.disabled = false;
  }
}

function setComposerDraftStatus(message, state = "blocked") {
  if (!agentComposerStatus) {
    return;
  }

  agentComposerStatus.textContent = message;
  agentComposerStatus.dataset.state = state;
}

async function createComposerTaskRun() {
  const prompt = agentComposerInput?.value.trim() ?? "";
  if (!prompt) {
    setComposerDraftStatus("Add a task prompt before drafting a blocked run.", "warning");
    agentComposerInput?.focus();
    return;
  }

  const invoke = tauriInvoke();
  if (!invoke) {
    setComposerDraftStatus("Browser preview only. Open in Tauri to persist a blocked OmegaTaskRun record.", "warning");
    renderCommandResolution({
      id: "agent.composer_draft",
      status: "blocked",
      target_command: "create_task_run_stub",
      reason: "Agent composer drafted locally, but persistent task-run storage requires the Tauri runtime.",
    });
    return;
  }

  agentComposerDraftBtn.disabled = true;
  setComposerDraftStatus("Drafting blocked OmegaTaskRun record...", "pending");

  try {
    const run = await invoke("create_task_run_stub", {
      request: {
        mode: "joint_ci",
        repo: "/home/rage/apps/gravity-omega-rust-rebuild",
        prompt,
      },
    });
    const records = await loadTaskRunLedger();
    const preview = await loadArtifactPreview(run.id);
    renderTaskRunLedger(records);
    renderArtifactPreview(preview);
    renderBottomEvidenceDock(records, preview);
    renderCodexHermesRunView(await loadCodexHermesRunViewDashboard());
    renderCommandResolution({
      id: "agent.composer_draft",
      status: run.status,
      target_command: "create_task_run_stub",
      reason: "Agent composer created a blocked OmegaTaskRun draft record; execution remains disabled.",
    });
    setComposerDraftStatus(`Drafted ${run.id}. Status: ${run.status}. Execution disabled.`, "ok");
    statusEl.textContent = `Agent composer drafted blocked run ${run.id}`;
    statusEl.classList.remove("error");
    statusEl.classList.add("ok");
  } catch (error) {
    setComposerDraftStatus(`Draft failed: ${error.message}`, "error");
    statusEl.textContent = `Agent composer draft failed: ${error.message}`;
    statusEl.classList.add("error");
  } finally {
    agentComposerDraftBtn.disabled = false;
  }
}

