async function recordHermesKimiAssistBrief({ prompt = "", orchestration = null, hermesInventory = null, timeoutMs = 15000 } = {}) {
  const focusSkills = (hermesInventory?.focus_skills ?? []).slice(0, 18);
  const mcpServers = (hermesInventory?.mcp_servers ?? [])
    .slice(0, 8)
    .map((server) => `${server.name ?? "mcp"} (${server.status ?? "unknown"}${server.tools ? `, tools=${server.tools}` : ""})`);
  const hooks = (hermesInventory?.hooks ?? [])
    .slice(0, 8)
    .map((hook) => `${hook.hook ?? "hook"}: ${hook.command ?? "command"}`);
  const invoke = tauriInvoke();
  if (!invoke) {
    return {
      id: "browser-preview",
      status: "browser_preview_no_hermes_kimi_assist",
      requested_by: "gravity-omega-ui",
      prompt_preview: limitText(String(prompt ?? "").trim(), 520),
      compact_query_preview: "",
      stdout: "",
      stderr: "",
      stdout_size_bytes: 0,
      stderr_size_bytes: 0,
      focus_skills: focusSkills,
      mcp_servers: mcpServers,
      hooks,
      record_path: "",
      blockers: ["Open in Tauri to run the bounded Hermes/Kimi assist brief."],
      next_step: "Run inside Gravity Omega Native to let Hermes/Kimi advise Codex Lead.",
    };
  }

  return invoke("record_hermes_kimi_assist_brief", {
    request: {
      prompt,
      requested_by: "gravity-omega-main-workflow",
      timeout_ms: timeoutMs,
      inventory_record_path: hermesInventory?.record_path || null,
      orchestration_record_path: orchestration?.record_path || null,
      focus_skills: focusSkills,
      mcp_servers: mcpServers,
      hooks,
    },
  });
}

