async function ensureTaskRunForApproval() {
  const runs = await loadTaskRunLedger();
  if (runs.length > 0) {
    return runs[0];
  }

  const invoke = tauriInvoke();
  return invoke("create_task_run_stub", {
    request: {
      mode: "joint_ci",
      repo: "/home/rage/apps/gravity-omega-rust-rebuild/rebuild/gravity-omega-tauri",
      prompt: "Create a blocked joint CI run before recording approval.",
    },
  });
}

async function ensureResolvedApprovalForRun(run) {
  const approvals = await loadApprovalLedger();
  const existing = approvals.find(
    (approval) =>
      approval.task_run_id === run.id &&
      approval.command_id === "agent.codex_review" &&
      approval.status === "approved_recorded_execution_disabled",
  );
  if (existing) {
    return existing;
  }

  const invoke = tauriInvoke();
  const approval = await invoke("create_approval_record_stub", {
    request: {
      subject_id: run.id,
      command_id: "agent.codex_review",
      task_run_id: run.id,
      capability_tier: "safe",
      risk_summary: "Codex review is allowlisted as read-only, but the runner remains disabled.",
      confirmation_phrase: "APPROVE CODEX REVIEW",
    },
  });

  return invoke("resolve_approval_record_stub", {
    request: {
      id: approval.id,
      decision: "approve",
      confirmation_text: approval.confirmation_phrase,
      note: "Auto-recorded for disabled runner prerequisite demo.",
    },
  });
}

