async function createTranscriptProtectionPolicyStub() {
  const invoke = tauriInvoke();
  if (!invoke) {
    statusEl.textContent = "Transcript protection policies require the Tauri runtime";
    statusEl.classList.add("error");
    return;
  }

  createProtectionPolicyBtn.disabled = true;
  try {
    let exportPolicyRecord = (await loadExportPolicyLedger()).find((record) => (
      record.status === "transcript_export_policy_recorded_export_disabled"
      && record.destination_kind === "local_file"
      && record.consent_required
      && !record.export_enabled
      && !record.writes_allowed
      && !record.execution_enabled
    ));

    if (!exportPolicyRecord) {
      const created = await createTranscriptExportPolicyStub();
      exportPolicyRecord = created?.policy;
    }

    if (!exportPolicyRecord) {
      throw new Error("No disabled transcript export policy is available for protection policy recording.");
    }

    const protectionPolicy = await invoke("create_transcript_protection_policy_stub", {
      request: {
        transcript_export_policy_id: exportPolicyRecord.id,
        requested_redaction_profile: "secrets_and_paths",
        requested_retention_tier: "local_30_days",
      },
    });

    renderProtectionPolicySummary(protectionPolicy.policy);
    renderProtectionPolicyLedger(await loadProtectionPolicyLedger());
    renderExportPolicySummary(exportPolicyRecord);
    renderExportPolicyLedger(await loadExportPolicyLedger());
    renderTranscriptBundleLedger(await loadTranscriptBundleLedger());
  } finally {
    createProtectionPolicyBtn.disabled = false;
  }
}

