function renderBottomEvidenceDock(records = [], preview = null) {
  if (!bottomEvidenceDock) {
    return;
  }

  clearList(bottomDockTaskRuns);
  bottomDockTaskRunCount.textContent = String(records.length);

  const recentRecords = records.slice(0, 5);
  if (recentRecords.length === 0) {
    bottomDockTaskRuns.append(item("No task runs yet", "empty", "Draft a blocked OmegaTaskRun from the agent composer."));
  } else {
    for (const record of recentRecords) {
      const view = describeTaskRecord(record);
      const node = item(view.title, view.meta, view.text);
      node.dataset.state = view.state;
      bottomDockTaskRuns.append(node);
    }
  }

  const latest = records[0];
  bottomDockStatus.textContent = latest
    ? `${records.length} task-run records. Latest: ${latest.id ?? "unknown"} / ${latest.status ?? "unknown"}.`
    : "No task-run evidence yet. Composer drafts remain blocked until execution gates are approved.";

  if (!preview) {
    bottomDockArtifactTitle.textContent = latest?.id ?? "none";
    bottomDockArtifactTail.textContent = latest
      ? "Artifact tail not loaded yet. Use the dock sync button or open an artifact preview."
      : "No artifact selected.";
    return;
  }

  bottomDockArtifactTitle.textContent = preview.found ? preview.id : "no artifact";
  bottomDockArtifactTail.textContent = preview.found
    ? [
        `record: ${preview.record_path}`,
        `log: ${preview.log_path}`,
        `lines: ${preview.line_count}${preview.truncated ? " (truncated)" : ""}`,
        "",
        ...(preview.log_lines ?? []),
      ].join("\n")
    : preview.error || preview.log_lines?.join("\n") || "No artifact available.";
}

