function renderReplacementAppShipReadiness(readiness) {
  if (!readiness) {
    shipReadinessSummary.textContent = "Ship readiness unavailable.";
    shipReadinessCount.textContent = "0";
    clearList(shipReadinessList);
    return;
  }

  shipReadinessSummary.textContent = [
    readiness.status,
    `families=${readiness.family_count}`,
    `ready=${readiness.product_ready_count}`,
    `partial=${readiness.partial_ready_count}`,
    `blocked=${readiness.blocked_count}`,
    `shipBlockers=${readiness.ship_blocker_count}`,
    `artifact=${readiness.release_artifact_ready}`,
    `binary=${readiness.release_binary_size_bytes ?? 0}b`,
    `exec=${readiness.execution_enabled}`,
  ].join(" | ");

  clearList(shipReadinessList);
  const rows = [...(readiness.items ?? [])].sort((left, right) => right.readiness_percent - left.readiness_percent);
  shipReadinessCount.textContent = String(rows.length);

  const headline = item(
    "Finish-line map",
    `${readiness.product_parity_feature_count} UI / ${readiness.electron_ipc_handler_count} IPC / ${readiness.flask_backend_route_count} Flask / ${readiness.registered_module_count} modules`,
    `${readiness.critical_blocker_count} critical blockers across ${readiness.target_command_family_count} command families. ${readiness.next_action}`,
  );
  headline.dataset.state = readiness.execution_enabled ? "gated" : "warning";
  shipReadinessList.append(headline);

  if (readiness.release_artifact) {
    const artifact = readiness.release_artifact;
    const artifactNode = item(
      `Release artifact: ${artifact.binary_name}`,
      `${artifact.exists ? "found" : "missing"} / ${artifact.size_bytes ?? 0}b / ${artifact.build_profile}`,
      [
        artifact.path,
        `package=${artifact.package_bundle_ready}; launcher=${artifact.desktop_launcher_ready}; install=${artifact.install_enabled}; launch=${artifact.launch_enabled}`,
        artifact.next_action,
      ].join(" "),
    );
    artifactNode.dataset.state = artifact.artifact_ready ? "ready" : "warning";
    shipReadinessList.append(artifactNode);
  }

  if (rows.length === 0) {
    shipReadinessList.append(item("No ship-readiness rows", "empty", "Refresh the finish-line blocker map."));
    return;
  }

  for (const row of rows) {
    const node = item(
      `${row.readiness_percent}% ${row.title}`,
      `${row.family_id} / ${row.status} / blockers=${row.blocker_count}`,
      `${row.critical_blocker} Next: ${row.next_action}`,
    );
    node.dataset.state = row.status.startsWith("blocked") ? "warning" : row.live_gate_ready ? "live" : "review";
    shipReadinessList.append(node);
  }
}

