function renderSidecarHealthPacketConsole(consoleState) {
  if (!consoleState) {
    sidecarHealthPacketSummary.textContent = "Sidecar health packet console unavailable.";
    sidecarHealthPacketCount.textContent = "0";
    clearList(sidecarHealthPacketList);
    return;
  }

  sidecarHealthPacketSummary.textContent = [
    consoleState.status,
    `packets=${consoleState.packet_count}`,
    `ready=${consoleState.packet_ready_count}`,
    `live_probes=${consoleState.live_probe_enabled_count}`,
    `blocked=${consoleState.blocked_launch_count}`,
    `runtime=${consoleState.running_runtime_target_count ?? 0}/${consoleState.runtime_process_snapshot_count ?? 0}`,
    `processes=${consoleState.live_process_count ?? 0}`,
    `hermes=${consoleState.hermes_runtime_process_count ?? 0}`,
    `sswp=${consoleState.sswp_runtime_process_count ?? 0}`,
    `steno=${consoleState.steno_runtime_process_count ?? 0}`,
    `spawn=${consoleState.spawn_enabled}`,
    `exec=${consoleState.execution_enabled}`,
  ].join(" | ");

  clearList(sidecarHealthPacketList);
  const packets = consoleState.packets ?? [];
  sidecarHealthPacketCount.textContent = String(packets.length);

  const headline = item(
    "Health packet console",
    `${consoleState.evidence_path_count} evidence paths / ${consoleState.approval_dependency_count} approval dependencies`,
    consoleState.next_action ?? "Define sidecar health packets before any sidecar launch.",
  );
  headline.dataset.state = consoleState.live_probe_enabled || consoleState.execution_enabled ? "gated" : "warning";
  sidecarHealthPacketList.append(headline);

  const processHeadline = item(
    "Live runtime process snapshot",
    `${consoleState.latest_runtime_process_snapshot_status ?? "runtime_sidecar_process_snapshot_waiting"} / running=${consoleState.running_runtime_target_count ?? 0} / processes=${consoleState.live_process_count ?? 0}`,
    `Hermes=${consoleState.hermes_runtime_process_count ?? 0}; SSWP=${consoleState.sswp_runtime_process_count ?? 0}; Steno=${consoleState.steno_runtime_process_count ?? 0}; Native=${consoleState.native_runtime_process_count ?? 0}; Codex=${consoleState.codex_runtime_process_count ?? 0}; record=${consoleState.latest_runtime_process_snapshot_path ?? "none"}`,
  );
  processHeadline.dataset.state = (consoleState.running_runtime_target_count ?? 0) > 0 ? "ok" : "warning";
  sidecarHealthPacketList.append(processHeadline);

  if (packets.length === 0) {
    sidecarHealthPacketList.append(item("No health packets", "empty", "Refresh the sidecar health packet console."));
    return;
  }

  for (const packet of packets) {
    const node = item(
      packet.title,
      `${packet.packet_id} / ${packet.sidecar_id} / ${packet.health_status}`,
      `${packet.probe_intent} Evidence: ${packet.evidence_path}. Blocker: ${packet.launch_blocker}`,
    );
    node.dataset.state = packet.packet_ready && !packet.live_probe_enabled ? "warning" : "disabled";
    sidecarHealthPacketList.append(node);
  }
}

async function refreshSidecarHealthPacketConsole() {
  refreshSidecarHealthPacketBtn.disabled = true;
  try {
    try {
      await recordRuntimeSidecarProcessSnapshot("gravity-omega-sidecar-health-console");
      await recordPetRuntimeSnapshotSignal("gravity-omega-sidecar-health-console");
    } catch (error) {
      setProblemText(`Runtime process snapshot failed: ${error.message}`);
    }
    const consoleState = await loadSidecarHealthPacketConsole();
    renderSidecarHealthPacketConsole(consoleState);
    return consoleState;
  } finally {
    refreshSidecarHealthPacketBtn.disabled = false;
  }
}

function renderRuntimeProbeBoard(board) {
  if (!board) {
    runtimeProbeSummary.textContent = "Runtime probe board unavailable.";
    runtimeProbeCount.textContent = "0";
    clearList(runtimeProbeList);
    return;
  }

  runtimeProbeSummary.textContent = [
    board.status,
    `ready=${board.ready_count}/${board.probe_count}`,
    `required=${board.required_ready_count}/${board.required_count}`,
    `missing=${board.missing_count}`,
    `failed=${board.failed_count}`,
    `bounded_spawn=${board.process_spawn_enabled}`,
    `launch=${board.sidecar_launch_enabled}`,
    `exec=${board.execution_enabled}`,
  ].join(" | ");

  clearList(runtimeProbeList);
  const results = board.results ?? [];
  runtimeProbeCount.textContent = String(results.length);

  const headline = item(
    "Bounded runtime probe substrate",
    `${board.required_ready_count}/${board.required_count} required ready / ${board.missing_count} missing / ${board.failed_count} failed`,
    board.next_action ?? "Run bounded probes before sidecar launch packets.",
  );
  headline.dataset.state = board.process_spawn_enabled && !board.execution_enabled ? "gated" : "warning";
  runtimeProbeList.append(headline);

  for (const blocker of board.blockers ?? []) {
    const node = item("Runtime blocker", "required runtime not ready", blocker);
    node.dataset.state = "warning";
    runtimeProbeList.append(node);
  }

  if (results.length === 0) {
    runtimeProbeList.append(item("No runtime probes", "empty", "Run all probes or choose a known runtime target."));
    return;
  }

  for (const result of results) {
    const output = result.stdout || result.stderr || result.evidence;
    const node = item(
      result.title,
      `${result.target} / ${result.binary} ${(result.args ?? []).join(" ")} / ${result.status}`,
      `${output} Required for: ${result.required_for}`,
    );
    node.dataset.state = result.status === "ready" ? "live" : result.status === "skipped" ? "disabled" : "warning";
    runtimeProbeList.append(node);
  }
}

async function runRuntimeProbes(target = "all") {
  runRuntimeProbesBtn.disabled = true;
  runtimeProbeSummary.textContent = "Running bounded runtime-depth probes...";
  try {
    const depth = await runRuntimeDepthProbe(target);
    const board = depth.board ?? await loadRuntimeProbeBoard(target);
    renderRuntimeProbeBoard(board);
    setOutputText([
      "Runtime depth probe recorded",
      `status=${depth.status}`,
      `runtime=${depth.runtime_ready_count}/${depth.runtime_probe_count}`,
      `required=${depth.required_runtime_ready_count}/${depth.required_runtime_count}`,
      `metadata=${depth.path_ready_count}/${depth.path_probe_count}`,
      `codex=${depth.codex_runtime_ready}`,
      `hermes=${depth.hermes_runtime_ready}`,
      `sswp=${depth.sswp_runtime_ready}`,
      `mcp_metadata=${depth.mcp_metadata_ready}`,
      `steno_metadata=${depth.steno_metadata_ready}`,
      `pet_metadata=${depth.pet_metadata_ready}`,
      `hermes_logs=${depth.hermes_log_preflight_status}`,
      `hermes_capability=${depth.hermes_capability_ready_count}/${depth.hermes_capability_probe_count}`,
      `hermes_skills=${depth.hermes_skill_count}`,
      `hermes_mcp=${depth.hermes_mcp_server_count}`,
      `hermes_hooks=${depth.hermes_hook_count}`,
      `qa_deferred=${depth.deep_interactive_qa_deferred}`,
      `record=${depth.record_path || "browser-preview"}`,
    ].join("\n"));
    appendEvidenceText(`runtime depth probe ${depth.status}: runtime=${depth.runtime_ready_count}/${depth.runtime_probe_count}; metadata=${depth.path_ready_count}/${depth.path_probe_count}; hermes_skills=${depth.hermes_skill_count}; hermes_mcp=${depth.hermes_mcp_server_count}; hooks=${depth.hermes_hook_count}; record=${depth.record_path || "browser-preview"}`);
    statusEl.textContent = board.process_spawn_enabled
      ? "Runtime depth probe recorded; sidecar launch remains disabled."
      : "Runtime depth probe preview loaded.";
    return board;
  } finally {
    runRuntimeProbesBtn.disabled = false;
  }
}

function renderRuntimeLaunchPackets(records) {
  clearList(runtimeLaunchPacketList);
  const rows = records ?? [];
  runtimeLaunchPacketCount.textContent = String(rows.length);

  if (rows.length === 0) {
    const node = item(
      "No runtime launch packets",
      "approval evidence empty",
      "Run bounded probes, then record launch packets for passing runtimes.",
    );
    node.dataset.state = "disabled";
    runtimeLaunchPacketList.append(node);
    return;
  }

  for (const record of rows) {
    const node = item(
      record.title,
      `${record.target} / ${record.status} / approval=${record.approval_required}`,
      `${record.binary} ${(record.args ?? []).join(" ")} -> ${record.probe_status}. Next: ${record.next_step}`,
    );
    node.dataset.state = record.launch_packet_recorded && !record.execution_enabled ? "gated" : "warning";
    runtimeLaunchPacketList.append(node);
  }
}

async function recordRuntimeLaunchPackets(target = "all") {
  recordRuntimeLaunchPacketsBtn.disabled = true;
  runtimeProbeSummary.textContent = "Recording runtime launch-packet evidence...";
  try {
    const result = await createRuntimeLaunchPacket(target);
    for (const blocker of result.blockers ?? []) {
      const node = item("Runtime packet blocker", result.requested_target, blocker);
      node.dataset.state = "warning";
      runtimeLaunchPacketList.prepend(node);
    }
    const packets = await loadRuntimeLaunchPackets();
    renderRuntimeLaunchPackets(packets);
    runtimeProbeSummary.textContent = [
      `launch_packets=${result.packet_count}`,
      `ready_probes=${result.ready_probe_count}/${result.probe_count}`,
      `approvals=${result.approval_required_count}`,
      `launch=${result.sidecar_launch_enabled}`,
      `exec=${result.execution_enabled}`,
    ].join(" | ");
    statusEl.textContent = result.accepted
      ? "Runtime launch packets recorded; launch still disabled."
      : "Runtime launch packets blocked by probe evidence.";
    return result;
  } finally {
    recordRuntimeLaunchPacketsBtn.disabled = false;
  }
}

