function renderWorkspaceExplorerSnapshot(snapshot) {
  if (!snapshot) {
    workspaceExplorerSummary.textContent = "Workspace explorer unavailable.";
    workspaceExplorerCount.textContent = "0";
    workspaceExplorerPreviewMeta.textContent = "No file";
    workspaceExplorerPreview.textContent = "No live workspace preview loaded.";
    clearList(workspaceExplorerTree);
    return;
  }

  workspaceExplorerSummary.textContent = [
    snapshot.status,
    `entries=${snapshot.entry_count}`,
    `dirs=${snapshot.directory_count}`,
    `files=${snapshot.file_count}`,
    `scoped=${snapshot.root_scope_valid}`,
    `read=${snapshot.file_read_enabled}`,
    `writes=${snapshot.writes_allowed}`,
    `exec=${snapshot.execution_enabled}`,
  ].join(" | ");

  clearList(workspaceExplorerTree);
  const entries = snapshot.entries ?? [];
  workspaceExplorerCount.textContent = String(entries.length);
  if (entries.length === 0) {
    workspaceExplorerTree.append(item("No live workspace entries", "empty", snapshot.next_step ?? "Load the scoped explorer in Tauri."));
  } else {
    for (const entry of entries.slice(0, 80)) {
      const node = item(
        entry.relative_path,
        `${entry.kind} | depth=${entry.depth} | ${entry.size_bytes}b`,
        entry.symlink ? "Symlink recorded but not followed." : snapshot.read_only ? "Read-only explorer entry." : "Explorer entry.",
      );
      node.dataset.state = entry.kind === "file" ? "ready" : "live";
      workspaceExplorerTree.append(node);
    }
  }

  const preview = snapshot.preview ?? {};
  workspaceExplorerPreviewMeta.textContent = `${preview.relative_path ?? "No file"} | ${preview.status ?? "unavailable"} | ${preview.bytes_read ?? 0}b`;
  workspaceExplorerPreview.textContent = preview.content || preview.reasons?.join("\n") || "No live workspace preview loaded.";
}

async function refreshWorkspaceExplorerSnapshot() {
  refreshWorkspaceExplorerBtn.disabled = true;
  try {
    const snapshot = await loadWorkspaceExplorerSnapshot();
    renderWorkspaceExplorerSnapshot(snapshot);
    return snapshot;
  } finally {
    refreshWorkspaceExplorerBtn.disabled = false;
  }
}

