function renderAgentEventPreview(preview) {
  agentEventCount.textContent = String(preview?.line_count ?? 0);
  if (!preview || !preview.found) {
    agentEventPreview.textContent = preview?.error ?? "No typed agent event log has been recorded yet.";
    return;
  }

  const rows = (preview.events ?? []).map((event) =>
    [
      `#${event.sequence}`,
      event.source_runtime,
      event.event_type,
      event.level,
      `execution=${event.execution_enabled}`,
      event.message,
    ].join(" | "),
  );
  agentEventPreview.textContent = [
    `log: ${preview.log_path}`,
    `events: ${preview.line_count}${preview.truncated ? " (truncated)" : ""}`,
    "",
    ...rows,
  ].join("\n");
}

