function renderEditableStatePreflightSummary(record) {
  if (!record) {
    editableStatePreflightSummary.textContent = "No editor buffer editable-state preflight recorded.";
    return;
  }

  editableStatePreflightSummary.textContent = [
    record.status,
    record.relative_path,
    `preflight=${record.editable_state_preflight_recorded}`,
    `editable=${record.buffer_appears_editable}`,
    `allowed=${record.editable_state_transition_allowed}`,
    `write=${record.file_write_enabled}`,
  ].join(" | ");
}

function renderEditableStatePreflightLedger(records) {
  clearList(editableStatePreflightLedger);
  editableStatePreflightCount.textContent = String(records.length);

  if (records.length === 0) {
    editableStatePreflightLedger.append(item("No editable-state preflights yet", "empty", "Record a disabled preflight before a buffer can appear editable."));
    return;
  }

  for (const record of records) {
    const view = describeEditableStatePreflight(record);
    const node = item(view.title, view.meta, view.text);
    node.dataset.state = view.state;
    editableStatePreflightLedger.append(node);
  }
}

