    renderLocalMcpConfigPathSealedConfigContentReadSchemaValidationFixtureRetentionReleasePublicationReleaseClosureReleaseFinalizationDryRunSummary(localMcpConfigPathSealedConfigContentReadSchemaValidationFixtureRetentionReleasePublicationReleaseClosureReleaseFinalizationDryRunRecords[0] ?? null);
    renderLocalMcpConfigPathSealedConfigContentReadSchemaValidationFixtureRetentionReleasePublicationReleaseClosureReleaseCompletionReviewDryRunSummary(localMcpConfigPathSealedConfigContentReadSchemaValidationFixtureRetentionReleasePublicationReleaseClosureReleaseCompletionReviewDryRunRecords[0] ?? null);
    renderLocalMcpConfigPathSealedConfigContentReadSchemaValidationFixtureRetentionReleasePublicationReleaseClosureReleaseReleaseReadinessDryRunSummary(localMcpConfigPathSealedConfigContentReadSchemaValidationFixtureRetentionReleasePublicationReleaseClosureReleaseReleaseReadinessDryRunRecords[0] ?? null);
    renderLocalMcpConfigPathSealedConfigContentReadSchemaValidationFixtureRetentionReleasePublicationReleaseClosureReleaseReleaseApprovalDryRunSummary(localMcpConfigPathSealedConfigContentReadSchemaValidationFixtureRetentionReleasePublicationReleaseClosureReleaseReleaseApprovalDryRunRecords[0] ?? null);
